echo ""
echo "Fase 8 aplicada. Pasos pendientes en tu Codespace:"
echo "  1) cd backend && npx prisma db push   (crea las tablas nuevas: delivery_zone, delivery_zone_rate, carrier_vehicle_type, y la columna customer.delivery_zone_id)"
echo "  2) npx prisma generate"
echo "  3) npx tsx src/scripts/import-fase8-zonas-tarifas.ts /ruta/al/excel.xlsx   (para cargar tu plantilla real -- revisa el resumen que imprime al final)"
echo "  4) Reinicia backend y frontend"
